/* ============================================================================
   Richardson Factory Direct 2026 — page styles
   ----------------------------------------------------------------------------
   Scope: calculators/richardson-2025.html ONLY (referenced by that page alone).
   Loads AFTER shared_components/css/calculator-base.css and
   calculator-modern-enhancements.css — reuse their tokens (--primary-green,
   --text-primary, etc.); only override where this page needs to.

   Design language ("refined corporate"):
   - Brand green is rationed to ONE job: signalling the price (and small accents).
     White text never sits on #4cb354 (2.66:1, fails AA) — use --rfd-green-ink.
   - Elevation comes from 1px hairlines + two surface tints (green = the answer,
     amber = caution), not shadows. Exactly one shadow token, for floating UI.
   - Two radii (10px container / 6px control) + one intentional pill.
   - No decorative or infinite motion. Transitions are functional only and are
     disabled under prefers-reduced-motion (locally + via the shared base).
   ============================================================================ */

/* ----------------------------------------------------------------------------
   Page-scoped tokens (do NOT redefine the shared brand tokens)
   ---------------------------------------------------------------------------- */

/* Page theme (CSS standardization, 2026-09-07): this page's own colours, auto-named by hue, merged into its
   existing :root. Map them to shared_components/css/tokens.css names when the page is redesigned;
   raw hex is allowed ONLY in this block. */
/* stylelint-disable color-no-hex */
:root {
    --richardson-2025-styles-red: #e4002b;
    --rfd-green-ink: var(--store-green-700);            /* accessible green: white text on it (5.1:1) and green text on white */
    --rfd-green-tint: var(--color-dash-theme-bg);           /* ~10% green wash — surface of "the answer" */
    --rfd-green-border: rgb(76 179 84 / 35%);
    --rfd-amber-bg: var(--store-paper);             /* LTM caution only */
    --rfd-amber-border: var(--amber-300);
    --rfd-amber-text: var(--amber-800);
    --rfd-amber-icon: var(--amber-600);
    --rfd-red: var(--richardson-2025-styles-red);                  /* Richardson brand red — one 3px keyline, nothing else */
    --rfd-radius: 10px;                  /* containers */
    --rfd-radius-sm: 6px;                /* controls, chips, tags */
    --rfd-radius-pill: 999px;            /* count badge + category chips only */
    --rfd-focus-ring: 0 0 0 3px var(--rfd-green-border);
    --rfd-shadow-float: 0 4px 12px rgb(0 0 0 / 6%);   /* the only shadow on the page */
    --rfd-transition: 150ms ease;
}
/* stylelint-enable color-no-hex */

/* ----------------------------------------------------------------------------
   Header — light touch (base styles the rest). Fix breadcrumb link contrast.
   ---------------------------------------------------------------------------- */
.breadcrumb a { color: var(--rfd-green-ink); }          /* base #4cb354 = 2.66:1, fails AA */
.breadcrumb a:hover { color: var(--primary-dark); }

/* ----------------------------------------------------------------------------
   Page header — title + Richardson logo, with one red brand keyline
   ---------------------------------------------------------------------------- */
.page-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1.5rem;
    border-top: 3px solid var(--rfd-red);
    padding-top: 1.25rem;
    margin-bottom: 1.5rem;
}

/* Solid, confident title — must out-rank base (.page-title 2rem) AND
   modern-enhancements (.page-title { font-size: var(--fluid-2xl) }). */
.page-header .page-title {
    margin: 0 0 0.25rem;
    font-size: 1.375rem;
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: -0.02em;
    color: var(--text-primary);
}

.page-header .page-subtitle {
    margin: 0;
    font-size: 0.875rem;
    font-weight: 400;
    color: var(--text-secondary);
}

.richardson-logo {
    height: 40px;
    width: auto;
    object-fit: contain;
    flex-shrink: 0;
}

/* ----------------------------------------------------------------------------
   SanMar notice — quiet neutral card with a green accent (was a loud blue alert)
   ---------------------------------------------------------------------------- */
.sanmar-notice {
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-left: 3px solid var(--primary-green);
    border-radius: var(--rfd-radius);
    padding: 1rem 1.25rem;
    margin-bottom: 1.5rem;
}

.sanmar-notice .notice-header {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    margin-bottom: 0.75rem;
}

.sanmar-notice .notice-header i {
    color: var(--primary-green);
    font-size: 1rem;
}

.sanmar-notice .notice-text strong {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--text-primary);
}

.sanmar-notice .notice-styles {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.style-link {
    display: inline-block;
    padding: 0.375rem 0.625rem;
    background: var(--bg-color);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius-sm);
    color: var(--text-primary);
    text-decoration: none;
    font-family: ui-monospace, 'SF Mono', Consolas, monospace;
    font-size: 0.8125rem;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    transition: border-color var(--rfd-transition), color var(--rfd-transition), background-color var(--rfd-transition);
}

.style-link:hover {
    border-color: var(--primary-green);
    color: var(--primary-dark);
    background: var(--hover-bg);
}

.style-link:focus-visible {
    outline: 2px solid var(--primary-dark);
    outline-offset: 2px;
}

/* ----------------------------------------------------------------------------
   Price lookup card
   ---------------------------------------------------------------------------- */
.pricing-card {
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius);
    padding: 1.5rem;
    margin-bottom: 1.5rem;
}

/* Scope beats base .section-title (1.125rem) and modern .section-title (fluid-2xl) */
.pricing-card .section-title {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin: 0 0 1.25rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid var(--border-color);
    font-size: 0.9375rem;
    font-weight: 600;
    letter-spacing: 0;
    color: var(--text-primary);
}

.pricing-card .section-title i {
    color: var(--primary-green);
    font-size: 0.875rem;
}

/* ----- Lookup form ----- */
.lookup-form {
    display: grid;
    gap: 1rem;
    margin-bottom: 1.25rem;
}

.lookup-form .form-group { margin-bottom: 0; }

/* Beats base `.form-group label` (0,1,1) */
.lookup-form .form-label {
    display: block;
    margin-bottom: 0.375rem;
    font-size: 0.8125rem;
    font-weight: 600;
    letter-spacing: 0.01em;
    color: var(--text-secondary);
}

.form-input {
    width: 100%;
    padding: 0.625rem 0.75rem;
    font-family: Inter, sans-serif;
    font-size: 0.9375rem;
    font-weight: 500;
    color: var(--text-primary);
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius-sm);
    transition: border-color 120ms ease, box-shadow 120ms ease;
}

.form-input::placeholder { color: var(--text-secondary); opacity: 0.8; }

.form-input:focus {
    outline: none;
    border-color: var(--primary-green);
    box-shadow: var(--rfd-focus-ring);
}

#quantity { font-variant-numeric: tabular-nums; }

.autocomplete-wrapper .form-input { padding-right: 2rem; }   /* room for the ✓ */

.style-description {
    min-height: 1.25rem;
    margin-top: 0.375rem;
    font-size: 0.8125rem;
    line-height: 1.4;
    color: var(--text-secondary);
}

.quantity-tier {
    margin-top: 0.375rem;
    font-size: 0.75rem;
    font-weight: 500;
    color: var(--text-secondary);
}

/* ----- Embellishment radios ----- */
.embellishment-options {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.5rem;
}

/* "New design" one-time-setup toggle, below the embellishment options */
.setup-toggle {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.625rem;
    font-size: 0.8125rem;
    color: var(--text-secondary);
    cursor: pointer;
}

.setup-toggle input[type="checkbox"] {
    width: 1rem;
    height: 1rem;
    flex-shrink: 0;
    accent-color: var(--primary-green);
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    min-height: 2.25rem;
    padding: 0.625rem 0.75rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius-sm);
    font-size: 0.875rem;
    color: var(--text-primary);
    cursor: pointer;
    transition: border-color var(--rfd-transition), background-color var(--rfd-transition);
}

.radio-option:hover { border-color: var(--primary-green); }

.radio-option input[type="radio"] {
    width: 1.05rem;
    height: 1.05rem;
    flex-shrink: 0;
    accent-color: var(--primary-green);
}

.radio-option input:checked + span {
    color: var(--rfd-green-ink);
    font-weight: 600;
}

.radio-option:has(input:checked) {
    border-color: var(--primary-green);
    background: var(--rfd-green-tint);
}

.radio-option:has(input:focus-visible) {
    border-color: var(--primary-green);
    box-shadow: var(--rfd-focus-ring);
}

/* ----------------------------------------------------------------------------
   Validation check + autocomplete dropdown
   ---------------------------------------------------------------------------- */
.validation-indicator {
    position: absolute;
    right: 0.75rem;
    top: 50%;
    transform: translateY(-50%);
    font-size: 1rem;
    opacity: 0;
    transition: opacity 120ms ease;
}

.validation-indicator.valid {
    color: var(--primary-green);
    opacity: 1;
}

.autocomplete-wrapper { position: relative; }

.autocomplete-list {
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    right: 0;
    z-index: 100;
    max-height: 280px;
    overflow-y: auto;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius);
    box-shadow: var(--rfd-shadow-float);
}

.autocomplete-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.625rem 0.875rem;
    border-bottom: 1px solid var(--border-color);
    cursor: pointer;
    transition: background-color var(--rfd-transition);
}

.autocomplete-item:last-child { border-bottom: none; }
.autocomplete-item:hover { background: var(--rfd-green-tint); }

.autocomplete-style {
    font-weight: 600;
    color: var(--text-primary);
    font-variant-numeric: tabular-nums;
}

.autocomplete-description {
    font-size: 0.8125rem;
    color: var(--text-secondary);
    text-align: right;
}

/* ----------------------------------------------------------------------------
   Price result — the hero. Renamed from .price-display so the base
   .price-display (2.5rem centred green box) can't leak into it.
   ---------------------------------------------------------------------------- */
.price-result {
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 7rem;
    padding: 1.5rem;
    background: var(--rfd-green-tint);
    border: 1px solid var(--rfd-green-border);
    border-radius: var(--rfd-radius);
}

.price-placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 1rem;
    text-align: center;
    color: var(--text-secondary);
}

.price-placeholder i { font-size: 1.75rem; opacity: 0.7; }
.price-placeholder span { font-size: 0.9375rem; }

.price-breakdown {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.price-row { display: flex; }

/* Reset the centred/secondary base .price-label inside this well */
.price-result .price-row .price-label {
    margin: 0;
    text-align: left;
}

/* Price Per Cap — eyebrow over a large green figure */
.price-row.price-total {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.125rem;
}

.price-row.price-total .price-label {
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--text-secondary);
}

.price-row.price-total .price-value {
    font-size: 2.25rem;
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: -0.02em;
    color: var(--rfd-green-ink);
    font-variant-numeric: tabular-nums;
}

/* Line Total — quiet ink row, deliberately ~half the price size */
.price-row.line-total {
    align-items: baseline;
    justify-content: space-between;
    gap: 0.75rem;
    padding-top: 0.75rem;
    border-top: 1px solid var(--rfd-green-border);
}

.price-row.line-total .price-label {
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--text-secondary);
}

.price-row.line-total .price-value {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--text-primary);
    font-variant-numeric: tabular-nums;
}

/* LTM caution */
.ltm-notice {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.625rem 0.75rem;
    background: var(--rfd-amber-bg);
    border: 1px solid var(--rfd-amber-border);
    border-radius: var(--rfd-radius-sm);
    font-size: 0.8125rem;
    color: var(--rfd-amber-text);
}

.ltm-notice i { color: var(--rfd-amber-icon); flex-shrink: 0; }

.ltm-per-unit {
    margin-left: auto;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
}

/* ----------------------------------------------------------------------------
   Cap browser — accordion (BUG #1: reveal keys off .expanded, matching the JS)
   ---------------------------------------------------------------------------- */
.cap-browser-accordion { margin-bottom: 1.5rem; }

.cap-browser-toggle {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding: 1rem 1.25rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius);
    cursor: pointer;
    font-family: Inter, sans-serif;
    transition: border-color var(--rfd-transition);
}

.cap-browser-toggle:hover { border-color: var(--primary-green); }

.cap-browser-toggle:focus-visible {
    outline: 2px solid var(--primary-dark);
    outline-offset: 2px;
}

.cap-browser-toggle[aria-expanded="true"] {
    border-radius: var(--rfd-radius) var(--rfd-radius) 0 0;
}

.cap-browser-toggle .toggle-header {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    font-size: 0.9375rem;
    font-weight: 600;
    color: var(--text-primary);
}

.cap-browser-toggle .toggle-header > i {
    color: var(--primary-green);
    font-size: 1rem;
}

.cap-count-badge {
    padding: 0.125rem 0.625rem;
    background: var(--rfd-green-ink);
    color: var(--color-on-brand);
    border-radius: var(--rfd-radius-pill);
    font-size: 0.75rem;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
}

.cap-browser-toggle .toggle-icon {
    color: var(--text-secondary);
    font-size: 0.875rem;
    transition: transform var(--rfd-transition);
}

.cap-browser-toggle[aria-expanded="true"] .toggle-icon { transform: rotate(180deg); }

.cap-browser-content { display: none; }

.cap-browser-content.expanded { display: block; }

.cap-browser-inner {
    padding: 1.25rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-top: none;
    border-radius: 0 0 var(--rfd-radius) var(--rfd-radius);
}

/* ----- Search ----- */
.cap-search-bar {
    position: relative;
    margin-bottom: 1rem;
}

.cap-search-bar > i.fa-search {
    position: absolute;
    left: 1rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--text-secondary);
    pointer-events: none;
}

.cap-search-bar .form-input {
    padding-left: 2.75rem;
    padding-right: 2.5rem;
}

.clear-search-btn {
    position: absolute;
    right: 0.625rem;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1.75rem;
    height: 1.75rem;
    background: none;
    border: none;
    border-radius: var(--rfd-radius-pill);
    color: var(--text-secondary);
    cursor: pointer;
    transition: background-color var(--rfd-transition), color var(--rfd-transition);
}

.clear-search-btn:hover { background: var(--hover-bg); color: var(--text-primary); }

.clear-search-btn:focus-visible {
    outline: 2px solid var(--primary-dark);
    outline-offset: 2px;
}

/* ----- Category chips ----- */
.cap-category-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-bottom: 1rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--border-color);
}

.category-chip {
    min-height: 1.875rem;
    padding: 0.375rem 0.875rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius-pill);
    color: var(--text-secondary);
    font-family: Inter, sans-serif;
    font-size: 0.8125rem;
    font-weight: 600;
    cursor: pointer;
    transition: border-color var(--rfd-transition), color var(--rfd-transition), background-color var(--rfd-transition);
}

.category-chip:hover { border-color: var(--primary-green); color: var(--primary-dark); }

.category-chip.active {
    background: var(--rfd-green-ink);
    border-color: var(--rfd-green-ink);
    color: var(--color-on-brand);
}

.category-chip:focus-visible {
    outline: 2px solid var(--primary-dark);
    outline-offset: 2px;
}

/* ----- Cap grid + cards (BUG #2: rules match the JS-emitted class names) ----- */
.cap-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.75rem;
    max-height: 400px;
    overflow-y: auto;
    padding-right: 0.25rem;
}

.cap-grid::-webkit-scrollbar { width: 6px; }
.cap-grid::-webkit-scrollbar-track { background: var(--bg-color); border-radius: var(--rfd-radius-pill); }
.cap-grid::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: var(--rfd-radius-pill); }
.cap-grid::-webkit-scrollbar-thumb:hover { background: var(--text-secondary); }

.cap-card {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    border-radius: var(--rfd-radius-sm);
    transition: border-color var(--rfd-transition), box-shadow var(--rfd-transition);
}

.cap-card:hover {
    border-color: var(--primary-green);
    box-shadow: var(--rfd-shadow-float);
}

.cap-card-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.5rem;
}

.cap-card .cap-style {
    font-size: 0.9375rem;
    font-weight: 700;
    color: var(--text-primary);
    font-variant-numeric: tabular-nums;
}

.cap-card .cap-category-badge {
    font-size: 0.6875rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--text-secondary);
    white-space: nowrap;
}

.cap-card-body {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.cap-card .cap-description {
    font-size: 0.8125rem;
    line-height: 1.4;
    color: var(--text-secondary);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.cap-card .cap-price {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--rfd-green-ink);
    font-variant-numeric: tabular-nums;
}

.quick-select-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.375rem;
    width: 100%;
    margin-top: auto;
    padding: 0.5rem 0.75rem;
    background: var(--rfd-green-ink);
    color: var(--color-on-brand);
    border: none;
    border-radius: var(--rfd-radius-sm);
    font-family: Inter, sans-serif;
    font-size: 0.8125rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color var(--rfd-transition);
}

.quick-select-btn:hover { background: var(--primary-dark); }

.quick-select-btn:focus-visible {
    outline: 2px solid var(--primary-dark);
    outline-offset: 2px;
}

.quick-select-btn i { font-size: 0.75rem; }

/* ----- Empty state ----- */
.no-caps-found {
    text-align: center;
    padding: 2.5rem 1rem;
    color: var(--text-secondary);
}

.no-caps-found i {
    display: block;
    margin-bottom: 0.5rem;
    font-size: 2rem;
    opacity: 0.7;
}

.no-caps-found p { margin: 0; font-size: 0.9375rem; }

/* ----------------------------------------------------------------------------
   Responsive
   ---------------------------------------------------------------------------- */
@media (width >= 768px) {
    .lookup-form {
        grid-template-columns: 1fr 1fr 1fr;
        gap: 1.5rem;
    }
}

@media (width <= 640px) {
    .page-header { flex-wrap: wrap; gap: 1rem; }

    .sanmar-notice,
    .pricing-card,
    .cap-browser-inner { padding: 1rem; }

    .price-result { padding: 1rem; }

    .cap-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); }

    /* Let chips scroll horizontally instead of wrapping into a tall block */
    .cap-category-filters {
        flex-wrap: nowrap;
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
    }

    .category-chip { flex-shrink: 0; }
}

/* ----------------------------------------------------------------------------
   Reduced motion — page is self-sufficient even if the shared block is dropped
   ---------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
    .breadcrumb a,
    .style-link,
    .form-input,
    .radio-option,
    .validation-indicator,
    .autocomplete-item,
    .cap-browser-toggle,
    .cap-browser-toggle .toggle-icon,
    .clear-search-btn,
    .category-chip,
    .cap-card,
    .quick-select-btn {
        transition: none;
    }
}

/* ----------------------------------------------------------------------------
   Print — a clean price slip (hide chrome the rep doesn't need on paper)
   ---------------------------------------------------------------------------- */
@media print {
    .sanmar-notice,
    .cap-browser-accordion { display: none; }

    .page-header { border-top: none; padding-top: 0; }

    .pricing-card { border: 1px solid var(--gray-300); }

    .price-result {
        background: var(--color-surface);
        border: 1px solid var(--gray-300);
    }
}

